Summon Celestial Aspect.command:
const actorUuid = 'Compendium.pf2e-team-plus-magic.actors.Actor.XwCNmhi9qFUDqfYW';
const effectUuid = 'Compendium.pf2e-team-plus-magic.misc.Item.GNSz5ksf9fux0j7u';

if (!window.foundrySummons) return ui.notifications.warn("Foundry Summons is not installed! Cannot automate summoning without it.");

let rank = 1;
let message;
let originItem;
if (scope.event) {
    const messageEl = scope.event.target.closest(".chat-message.message")
    if (messageEl) {
        const messageId = messageEl.dataset.messageId;
        message = game.messages.get(messageId);
        if (message) {
            originItem = message.item;
            rank = message.item.rank;
            if (message.token) token = message.token;
        }
    }
} else {
  const highestRank = Math.max(...token.actor.spellcasting.collections.contents.map(x => x.highestRank));
  const data = await foundry.applications.api.DialogV2.input({
    window: { title: "Pick spell rank" },
    content: `<select name="rank">
    ${Array.from({ length: highestRank }, (_, i) => `<option value="${i + 1}">${i + 1}</option>`).join("")}
  </select>`,
    ok: {
      label: "Save",
      icon: "fa-solid fa-floppy-disk",
    }
  })

  rank = data.rank;
}

if (!token) return ui.notifications.warn("Select the summoning token before summoning.");

const actorDoc = await fromUuid(actorUuid);
const summon = await foundrySummons.pick({ 
    actor: actorDoc, 
    updateData: {
        system: {
            details: {
                level: {
                    value: rank
                }
            }
        }
    }
})

const effectDoc = await fromUuid(effectUuid);
const effect = effectDoc.toObject()
const spellcasting =
  originItem?.isOfType("spell") && originItem.spellcasting
      ? {
            attribute: {
                type: originItem.attribute,
                mod: originItem.spellcasting.statistic?.attributeModifier?.value ?? 0,
            },
            tradition: originItem.spellcasting.tradition,
        }
      : null;

effect.system.level.value = rank;
effect.system.context = {
    origin: {
        actor: token.actor.uuid,
        token: message?.token.uuid || token.uuid,
        item: message?.item.uuid,
        rollOptions: message?.flags.pf2e.origin?.rollOptions ?? [],
        spellcasting,
    }
};

game.actors.get(summon.actorId)?.createEmbeddedDocuments("Item", [effect])

